/**
 * Header validation and storage for the portable node:http shim.
 *
 * The operation mapping follows nodejs/node v24.19.0, commit
 * cdc1b38d40cb567b7ad0b39c86addf830a0af0ae, lib/_http_outgoing.js,
 * lib/_http_common.js, and lib/_http_incoming.js (MIT license). Node's
 * kOutHeaders store and header-line folding are reimplemented over a typed
 * Map so headers can cross the WIT boundary as byte fields.
 */
import { headerAlreadySent, invalidArgType, invalidHeaderChar, invalidHttpToken, } from "./errors.js";
const TOKEN = /^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/;
const INVALID_VALUE = /[\0\r\n]/;
export function validateHeaderName(name, label = "Header name") {
    if (typeof name !== "string") {
        throw invalidArgType("name", "string", name);
    }
    if (!TOKEN.test(name)) {
        throw invalidHttpToken(label, name);
    }
}
export function validateHeaderValue(name, value) {
    if (value === undefined) {
        throw invalidArgType("value", "string", value);
    }
    if (INVALID_VALUE.test(String(value))) {
        throw invalidHeaderChar(name);
    }
}
function values(value) {
    return (Array.isArray(value) ? value : [value]).map(String);
}
export class HeaderStore {
    #headers = new Map();
    #sent = false;
    constructor(headers) {
        if (Array.isArray(headers)) {
            if (headers.length % 2 !== 0) {
                throw invalidArgType("headers", "an even-length array", headers);
            }
            for (let index = 0; index < headers.length; index += 2) {
                this.append(headers[index], headers[index + 1]);
            }
        }
        else if (headers) {
            for (const [name, value] of Object.entries(headers)) {
                if (value !== undefined) {
                    this.set(name, value);
                }
            }
        }
    }
    markSent() {
        this.#sent = true;
    }
    get sent() {
        return this.#sent;
    }
    set(name, value) {
        this.#assertMutable();
        this.setInternal(name, value);
    }
    setInternal(name, value) {
        validateHeaderName(name);
        for (const item of values(value)) {
            validateHeaderValue(name, item);
        }
        this.#headers.set(name.toLowerCase(), {
            name,
            value: Array.isArray(value) ? [...value] : value,
        });
    }
    append(name, value) {
        this.#assertMutable();
        const current = this.#headers.get(name.toLowerCase());
        if (!current) {
            this.set(name, value);
            return;
        }
        this.set(current.name, [...values(current.value), ...values(value)]);
    }
    get(name) {
        return this.#headers.get(name.toLowerCase())?.value;
    }
    has(name) {
        return this.#headers.has(name.toLowerCase());
    }
    delete(name) {
        this.#assertMutable();
        this.#headers.delete(name.toLowerCase());
    }
    names() {
        return [...this.#headers.keys()];
    }
    rawNames() {
        return [...this.#headers.values()].map(({ name }) => name);
    }
    object() {
        const result = Object.create(null);
        for (const [name, { value }] of this.#headers) {
            result[name] = Array.isArray(value) ? [...value] : value;
        }
        return result;
    }
    entries() {
        return [...this.#headers.values()].flatMap(({ name, value }) => values(value).map((item) => [name, item]));
    }
    fields() {
        return this.entries().map(([name, value]) => ({
            name,
            value: Uint8Array.from(value, (character) => character.charCodeAt(0) & 0xff),
        }));
    }
    #assertMutable() {
        if (this.#sent) {
            throw headerAlreadySent();
        }
    }
}
export function incomingHeaders(headers) {
    const decoder = new TextDecoder("latin1");
    const result = {};
    const rawHeaders = [];
    for (const { name, value } of headers) {
        const text = decoder.decode(value);
        rawHeaders.push(name, text);
        const lower = name.toLowerCase();
        const current = result[lower];
        if (lower === "set-cookie") {
            result[lower] =
                current === undefined ? [text] : [...(Array.isArray(current) ? current : [current]), text];
        }
        else if (current === undefined) {
            result[lower] = text;
        }
        else {
            result[lower] = `${Array.isArray(current) ? current.join(", ") : current}, ${text}`;
        }
    }
    return { headers: result, rawHeaders };
}
